#!/usr/bin/env node
// Writes .env.local from the running local Supabase stack (`npx supabase start`).
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const out = execFileSync("npx", ["supabase", "status", "-o", "json"], { encoding: "utf8" });
const status = JSON.parse(out.slice(out.indexOf("{")));
writeFileSync(
  ".env.local",
  [
    "# Generated by `npm run db:env` for the local Supabase stack. Not committed.",
    `NEXT_PUBLIC_SUPABASE_URL=${status.API_URL}`,
    `NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${status.PUBLISHABLE_KEY}`,
    "",
  ].join("\n"),
);
console.log("Wrote .env.local for", status.API_URL);
